# build.sh -- builds this OnOff_Serial example for a Microchip SAM (Cortex-M) part with
# arm-none-eabi-gcc, against MPLAB Harmony 3 code generated by MCC, without MPLAB X / XC32.
#
# Run from Git Bash (Windows), or bash on Linux / macOS:
#   bash build.sh               build
#   bash build.sh --delete-sdk  build, then delete anything build.sh downloaded
# Output, in build/ in this directory: OnOff_Serial.elf / .map / .hex / .bin
# Flash with MPLAB IPE, or e.g. openocd / edbg for the Xplained Pro boards.
#
# The MCC generated code comes from (first found):
#   1. SAM_MCC_SRC, your MCC Harmony 3 project's firmware/src directory, with
#        - a SERCOM USART PLIB in "Ring buffer" mode (main.cpp uses SERCOM3)
#        - the LED pin named LED (see target_Pin.cpp), or PFOD_PIN set below
#      and SAM_MCC_CONFIG, its configuration name under firmware/src/config (default "default")
#   2. otherwise Microchip's own generated SAM D21 Xplained Pro project (ATSAMD21J18A,
#      SERCOM3 Ring buffer USART = the board's EDBG virtual COM port), apps/sercom/usart/
#      usart_ring_buffer_interrupt of github.com/Microchip-MPLAB-Harmony/csp_apps_sam_d21_da1,
#      sparse cloned into build/ (needs git). Built with PFOD_PIN = PORT_PIN_PB30 (LED0) and
#      PFOD_PIN_ON_LEVEL = 0, as that project has no pin named LED.
# Everything in the MCC config directory is compiled, except MCC's XC32 only startup_xc32.c,
# plus this example (whose main.cpp replaces MCC's main.c) and pfodParserCPP.
# MCC's XC32 linker script is not gcc compatible, so the device pack's gcc startup and
# linker script are used instead; the startup's own vector table is removed, so MCC's
# interrupts.c vector table (which routes the SERCOM interrupt to the PLIB) is used.
#
# Other settings (environment variables):
#   SAM_DEVICE     the part, lower case, as in the device pack's file names, default samd21j18a
#   SAM_DFP        the device pack's family directory (holding include/ and gcc/gcc/), e.g. an
#                  unzipped Microchip.SAMD21_DFP.*.atpack's samd21a/. Otherwise the SAMD21 DFP
#                  3.8.270 (about 10MB) is downloaded into build/ (needs curl and unzip).
#   SAM_MCU_FLAGS  default "-mcpu=cortex-m0plus -mthumb" (SAM D2x / C2x / L2x). For SAM D5x / E5x
#                  use "-mcpu=cortex-m4 -mthumb -mfloat-abi=hard -mfpu=fpv4-sp-d16"
#   PFOD_PIN / PFOD_PIN_ON_LEVEL  passed to target_Pin.cpp if set, e.g. PFOD_PIN=PORT_PIN_PB30
#   SAM_GCC_BIN    the bin directory of arm-none-eabi-gcc, otherwise from the PATH, otherwise
#                  the highest packages/*/tools/arm-none-eabi-gcc/*/bin in Arduino15
#   ARDUINO15      overrides the Arduino15 location
# The CMSIS core headers come from the highest packages/*/tools/CMSIS/*/CMSIS/Include in
# Arduino15, otherwise they are downloaded from github.com/ARM-software/CMSIS_5.
# PFOD_PARSER_CPP overrides the pfodParserCPP directory, default three directories up from here.

set -u

DFP_URL=https://packs.download.microchip.com/Microchip.SAMD21_DFP.3.8.270.atpack
APPS_URL=https://github.com/Microchip-MPLAB-Harmony/csp_apps_sam_d21_da1.git
APP_PATH=apps/sercom/usart/usart_ring_buffer_interrupt/firmware/src
CMSIS_URL=https://raw.githubusercontent.com/ARM-software/CMSIS_5/develop/CMSIS/Core/Include
SAM_DEVICE="${SAM_DEVICE:-samd21j18a}"
SAM_MCU_FLAGS="${SAM_MCU_FLAGS:--mcpu=cortex-m0plus -mthumb}"

EX="$(cd "$(dirname "$0")" && pwd)"
ROOT="${PFOD_PARSER_CPP:-$EX/../../..}"
OUT="$EX/build"
DL="$OUT/download"
DELETE_SDK=0
[ "${1:-}" = "--delete-sdk" ] && DELETE_SDK=1

# toPath -- convert a path for the native tools (C:/... form under Git Bash on Windows)
toPath() {
  if command -v cygpath >/dev/null 2>&1; then cygpath -m "$1"; else echo "$1"; fi
}

# fail -- print an error and stop
fail() {
  echo "ERROR: $*" >&2
  exit 1
}

if [ -z "${ARDUINO15:-}" ]; then
  if [ -n "${LOCALAPPDATA:-}" ]; then ARDUINO15="$(toPath "$LOCALAPPDATA")/Arduino15"
  elif [ "$(uname)" = "Darwin" ]; then ARDUINO15="$HOME/Library/Arduino15"
  else ARDUINO15="$HOME/.arduino15"; fi
fi

# ---- toolchain ----
if [ -n "${SAM_GCC_BIN:-}" ]; then
  TC="$SAM_GCC_BIN/arm-none-eabi-"
elif command -v arm-none-eabi-gcc >/dev/null 2>&1; then
  TC="arm-none-eabi-"
else
  TCDIR="$(ls -d "$ARDUINO15"/packages/*/tools/arm-none-eabi-gcc/*/bin 2>/dev/null | sort -V | tail -1)"
  [ -n "$TCDIR" ] || fail "no arm-none-eabi-gcc found, set SAM_GCC_BIN"
  TC="$TCDIR/arm-none-eabi-"
fi
"${TC}gcc" --version >/dev/null 2>&1 || fail "cannot run ${TC}gcc"
echo "Toolchain: $("${TC}gcc" --version | head -1)"

# ---- MCC generated code ----
PIN_DEFS=""
if [ -n "${SAM_MCC_SRC:-}" ]; then
  MCC_SRC="$SAM_MCC_SRC"
  CFG="$MCC_SRC/config/${SAM_MCC_CONFIG:-default}"
else
  MCC_SRC="$DL/csp_apps/$APP_PATH"
  CFG="$MCC_SRC/config/sam_d21_xpro"
  if [ ! -f "$CFG/definitions.h" ]; then
    echo "Downloading Microchip's generated SAM D21 Xplained Pro ring buffer USART project into $DL"
    rm -rf "$DL/csp_apps"
    mkdir -p "$DL"
    git clone -q --depth 1 --filter=blob:none --sparse "$APPS_URL" "$DL/csp_apps" || fail "git clone of csp_apps_sam_d21_da1 failed"
    git -C "$DL/csp_apps" sparse-checkout set "$APP_PATH" || fail "git sparse-checkout failed"
  fi
  PIN_DEFS="-DPFOD_PIN=PORT_PIN_PB30 -DPFOD_PIN_ON_LEVEL=0" # the Xplained Pro's LED0
fi
[ -f "$CFG/definitions.h" ] || fail "$CFG/definitions.h not found, check SAM_MCC_SRC and SAM_MCC_CONFIG"
[ -n "${PFOD_PIN:-}" ] && PIN_DEFS="-DPFOD_PIN=$PFOD_PIN"
[ -n "${PFOD_PIN_ON_LEVEL:-}" ] && PIN_DEFS="$PIN_DEFS -DPFOD_PIN_ON_LEVEL=$PFOD_PIN_ON_LEVEL"
echo "MCC config: $CFG"

# ---- device pack ----
if [ -n "${SAM_DFP:-}" ]; then
  DFP="$SAM_DFP"
else
  DFP="$DL/dfp/samd21a"
  if [ ! -d "$DFP/include" ]; then
    echo "Downloading the SAMD21 device pack into $DL"
    mkdir -p "$DL"
    curl -fL -sS -o "$DL/dfp.atpack" "$DFP_URL" || fail "download of the SAMD21 device pack failed"
    (cd "$DL" && unzip -q -o dfp.atpack -d dfp) || fail "unzip of the SAMD21 device pack failed"
    rm -f "$DL/dfp.atpack"
  fi
fi
STARTUP="$DFP/gcc/gcc/startup_$SAM_DEVICE.c"
LDSCRIPT="$DFP/gcc/gcc/${SAM_DEVICE}_flash.ld"
[ -f "$STARTUP" ] && [ -f "$LDSCRIPT" ] || fail "no gcc startup / linker script for $SAM_DEVICE in $DFP/gcc/gcc"
DEVICE_DEF="-D__$(echo "$SAM_DEVICE" | tr 'a-z' 'A-Z')__"

# ---- CMSIS core headers ----
CMSIS="$(ls -d "$ARDUINO15"/packages/*/tools/CMSIS/*/CMSIS/Include 2>/dev/null | sort -V | tail -1)"
if [ -z "$CMSIS" ] || [ ! -f "$CMSIS/core_cm0plus.h" ]; then
  CMSIS="$DL/cmsis"
  if [ ! -f "$CMSIS/core_cm0plus.h" ]; then
    echo "Downloading the CMSIS core headers into $CMSIS"
    mkdir -p "$CMSIS"
    for f in core_cm0plus.h core_cm4.h core_cm7.h cmsis_compiler.h cmsis_gcc.h cmsis_version.h mpu_armv7.h cachel1_armv7.h; do
      curl -sfL -o "$CMSIS/$f" "$CMSIS_URL/$f" || fail "download of $f failed"
    done
  fi
fi

# ---- build ----
rm -rf "$OUT/obj" "$OUT/mcc" "$OUT"/OnOff_Serial.*
mkdir -p "$OUT/obj" "$OUT/mcc"
: > "$OUT/warnings.txt"

P() { toPath "$1"; }
INC="-I$(P "$EX") -I$(P "$ROOT/src") -I$(P "$CFG") -I$(P "$MCC_SRC") -I$(P "$DFP/include") -I$(P "$CMSIS")"
COMMON="$SAM_MCU_FLAGS $DEVICE_DEF $INC -Os -g -ffunction-sections -fdata-sections"

errors=0
# MCC's generated code, its warnings are not shown. Object names include the directory,
# as MCC has some files with the same name in different directories.
while IFS= read -r f; do
  rel="${f#$CFG/}"
  "${TC}gcc" -c -std=gnu99 $COMMON -w "$(P "$f")" -o "$(P "$OUT/mcc/$(echo "${rel%.*}" | tr '/' '_').o")" \
    || { echo "compile failed: $f"; errors=1; }
done < <(find "$CFG" -type f -name '*.c' ! -name startup_xc32.c)
# the device pack's gcc startup, without its vector table (MCC's interrupts.c has the one used)
"${TC}gcc" -c -std=gnu99 $COMMON -w "$(P "$STARTUP")" -o "$(P "$OUT/mcc/dfp_startup.o")" \
  && "${TC}objcopy" --strip-debug --remove-section=.vectors "$(P "$OUT/mcc/dfp_startup.o")" \
  || { echo "compile failed: $STARTUP"; errors=1; }
# this example and pfodParserCPP, with warnings
for f in "$EX"/*.cpp "$ROOT"/src/*.cpp "$ROOT"/src/dwgs/*.cpp; do
  "${TC}g++" -c -std=gnu++11 $COMMON $PIN_DEFS -Wall -Wextra -fno-exceptions -fno-rtti -fno-threadsafe-statics \
    "$(P "$f")" -o "$(P "$OUT/obj/$(basename "${f%.*}").o")" 2>>"$OUT/warnings.txt" || { echo "compile failed: $f"; errors=1; }
done
for f in "$ROOT"/src/*.c; do
  "${TC}gcc" -c -std=gnu99 $COMMON -Wall -Wextra "$(P "$f")" -o "$(P "$OUT/obj/$(basename "${f%.*}").o")" 2>>"$OUT/warnings.txt" || { echo "compile failed: $f"; errors=1; }
done
[ -s "$OUT/warnings.txt" ] && cat "$OUT/warnings.txt"
[ $errors = 0 ] || fail "compile failed"

# _stack: MCC's vector table uses _stack for the initial stack pointer, the pack's
# linker script calls it _estack
"${TC}g++" $SAM_MCU_FLAGS "-T$(P "$LDSCRIPT")" -Wl,--defsym=_stack=_estack -Wl,--gc-sections \
  "-Wl,-Map=$(P "$OUT/OnOff_Serial.map")" --specs=nano.specs --specs=nosys.specs \
  "$(P "$OUT")"/mcc/*.o "$(P "$OUT")"/obj/*.o -o "$(P "$OUT/OnOff_Serial.elf")" || fail "link failed"
"${TC}size" "$(P "$OUT/OnOff_Serial.elf")"
"${TC}objcopy" -O ihex "$(P "$OUT/OnOff_Serial.elf")" "$(P "$OUT/OnOff_Serial.hex")"
"${TC}objcopy" -O binary "$(P "$OUT/OnOff_Serial.elf")" "$(P "$OUT/OnOff_Serial.bin")"
echo "Built $OUT/OnOff_Serial.elf / .hex / .bin"

if [ $DELETE_SDK = 1 ]; then
  rm -rf "$DL"
  echo "Deleted the downloads in $DL"
fi
